     1→/**
     2→ * AnyType Workspace Sync Helper for OpenClaw
     3→ *
     4→ * Simple interface to write, update, and delete notes in AnyType
     5→ * via the filesystem-based sync service.
     6→ *
     7→ * Usage:
     8→ *   const AnyType = require('./anytype-helper');
     9→ *   const anytype = new AnyType();
    10→ *
    11→ *   await anytype.write('meeting-notes', 'Meeting Notes', 'Discussion about...');
    12→ *   await anytype.update('meeting-notes', 'Updated content...');
    13→ *   await anytype.delete('meeting-notes');
    14→ */
    15→
    16→const fs = require('fs').promises;
    17→const path = require('path');
    18→
    19→class AnyTypeHelper {
    20→    constructor(workspaceDir = '/root/anytype-workspace') {
    21→        this.workspaceDir = workspaceDir;
    22→    }
    23→
    24→    /**
    25→     * Write a new note to AnyType
    26→     *
    27→     * @param {string} id - Unique identifier for the note (used as filename)
    28→     * @param {string} title - Note title (will be the first heading)
    29→     * @param {string} content - Note content (markdown)
    30→     * @returns {Promise<void>}
    31→     *
    32→     * @example
    33→     * await anytype.write('daily-log', 'Daily Log', 'Today I worked on...');
    34→     */
    35→    async write(id, title, content) {
    36→        const filepath = path.join(this.workspaceDir, `${id}.md`);
    37→        const markdown = `# ${title}\n\n${content}`;
    38→
    39→        try {
    40→            await fs.writeFile(filepath, markdown, 'utf8');
    41→            console.log(`[AnyType] ✓ Written: ${id}`);
    42→        } catch (error) {
    43→            console.error(`[AnyType] ✗ Write failed for ${id}:`, error.message);
    44→            throw error;
    45→        }
    46→    }
    47→
    48→    /**
    49→     * Update an existing note (or create if doesn't exist)
    50→     *
    51→     * @param {string} id - Note identifier
    52→     * @param {string} content - Full markdown content (must include # Title)
    53→     * @returns {Promise<void>}
    54→     *
    55→     * @example
    56→     * await anytype.update('daily-log', '# Daily Log\n\nUpdated content...');
    57→     */
    58→    async update(id, content) {
    59→        const filepath = path.join(this.workspaceDir, `${id}.md`);
    60→
    61→        try {
    62→            await fs.writeFile(filepath, content, 'utf8');
    63→            console.log(`[AnyType] ✓ Updated: ${id}`);
    64→        } catch (error) {
    65→            console.error(`[AnyType] ✗ Update failed for ${id}:`, error.message);
    66→            throw error;
    67→        }
    68→    }
    69→
    70→    /**
    71→     * Delete a note from AnyType
    72→     *
    73→     * @param {string} id - Note identifier
    74→     * @returns {Promise<void>}
    75→     *
    76→     * @example
    77→     * await anytype.delete('old-note');
    78→     */
    79→    async delete(id) {
    80→        const filepath = path.join(this.workspaceDir, `${id}.md`);
    81→
    82→        try {
    83→            await fs.unlink(filepath);
    84→            console.log(`[AnyType] ✓ Deleted: ${id}`);
    85→        } catch (error) {
    86→            if (error.code === 'ENOENT') {
    87→                console.warn(`[AnyType] ⚠ Already deleted: ${id}`);
    88→            } else {
    89→                console.error(`[AnyType] ✗ Delete failed for ${id}:`, error.message);
    90→                throw error;
    91→            }
    92→        }
    93→    }
    94→
    95→    /**
    96→     * Read a note's content
    97→     *
    98→     * @param {string} id - Note identifier
    99→     * @returns {Promise<string>} Note content
   100→     *
   101→     * @example
   102→     * const content = await anytype.read('daily-log');
   103→     */
   104→    async read(id) {
   105→        const filepath = path.join(this.workspaceDir, `${id}.md`);
   106→
   107→        try {
   108→            return await fs.readFile(filepath, 'utf8');
   109→        } catch (error) {
   110→            if (error.code === 'ENOENT') {
   111→                return null;
   112→            }
   113→            console.error(`[AnyType] ✗ Read failed for ${id}:`, error.message);
   114→            throw error;
   115→        }
   116→    }
   117→
   118→    /**
   119→     * Check if a note exists
   120→     *
   121→     * @param {string} id - Note identifier
   122→     * @returns {Promise<boolean>}
   123→     *
   124→     * @example
   125→     * if (await anytype.exists('daily-log')) { ... }
   126→     */
   127→    async exists(id) {
   128→        const filepath = path.join(this.workspaceDir, `${id}.md`);
   129→
   130→        try {
   131→            await fs.access(filepath);
   132→            return true;
   133→        } catch {
   134→            return false;
   135→        }
   136→    }
   137→
   138→    /**
   139→     * List all synced note IDs
   140→     *
   141→     * @returns {Promise<string[]>} Array of note IDs
   142→     *
   143→     * @example
   144→     * const notes = await anytype.list();
   145→     * console.log('Synced notes:', notes);
   146→     */
   147→    async list() {
   148→        try {
   149→            const files = await fs.readdir(this.workspaceDir);
   150→            return files
   151→                .filter(f => f.endsWith('.md'))
   152→                .map(f => f.replace('.md', ''));
   153→        } catch (error) {
   154→            console.error('[AnyType] ✗ List failed:', error.message);
   155→            throw error;
   156→        }
   157→    }
   158→
   159→    /**
   160→     * Append content to an existing note
   161→     *
   162→     * @param {string} id - Note identifier
   163→     * @param {string} content - Content to append
   164→     * @returns {Promise<void>}
   165→     *
   166→     * @example
   167→     * await anytype.append('daily-log', '\n\n## Update\nNew information...');
   168→     */
   169→    async append(id, content) {
   170→        const filepath = path.join(this.workspaceDir, `${id}.md`);
   171→
   172→        try {
   173→            await fs.appendFile(filepath, content, 'utf8');
   174→            console.log(`[AnyType] ✓ Appended to: ${id}`);
   175→        } catch (error) {
   176→            console.error(`[AnyType] ✗ Append failed for ${id}:`, error.message);
   177→            throw error;
   178→        }
   179→    }
   180→
   181→    /**
   182→     * Format a MongoDB document as markdown note
   183→     *
   184→     * @param {Object} doc - MongoDB document
   185→     * @param {string} doc._id - Document ID
   186→     * @param {string} doc.title - Document title
   187→     * @param {Object} doc - Other document fields
   188→     * @returns {Object} {id, title, content}
   189→     *
   190→     * @example
   191→     * const note = anytype.formatFromMongo(mongoDoc);
   192→     * await anytype.write(note.id, note.title, note.content);
   193→     */
   194→    formatFromMongo(doc) {
   195→        const id = `mongo-${doc._id}`;
   196→        const title = doc.title || `Document ${doc._id}`;
   197→
   198→        let content = '';
   199→
   200→        // Add timestamp if available
   201→        if (doc.createdAt) {
   202→            content += `**Created**: ${new Date(doc.createdAt).toISOString()}\n\n`;
   203→        }
   204→
   205→        // Add all fields except internal ones
   206→        for (const [key, value] of Object.entries(doc)) {
   207→            if (key.startsWith('_') || key === 'title' || key === 'createdAt') {
   208→                continue;
   209→            }
   210→
   211→            if (typeof value === 'object') {
   212→                content += `## ${key}\n\`\`\`json\n${JSON.stringify(value, null, 2)}\n\`\`\`\n\n`;
   213→            } else {
   214→                content += `**${key}**: ${value}\n\n`;
   215→            }
   216→        }
   217→
   218→        return { id, title, content: content.trim() };
   219→    }
   220→
   221→    /**
   222→     * Sync a MongoDB document to AnyType
   223→     *
   224→     * @param {Object} doc - MongoDB document
   225→     * @returns {Promise<void>}
   226→     *
   227→     * @example
   228→     * mongoChangeStream.on('change', async (change) => {
   229→     *     await anytype.syncFromMongo(change.fullDocument);
   230→     * });
   231→     */
   232→    async syncFromMongo(doc) {
   233→        const { id, title, content } = this.formatFromMongo(doc);
   234→        await this.write(id, title, content);
   235→    }
   236→
   237→    /**
   238→     * Create a timestamped log entry
   239→     *
   240→     * @param {string} title - Log title
   241→     * @param {string} content - Log content
   242→     * @param {string} [prefix='log'] - Filename prefix
   243→     * @returns {Promise<string>} Generated ID
   244→     *
   245→     * @example
   246→     * const logId = await anytype.log('System Event', 'Server restarted');
   247→     */
   248→    async log(title, content, prefix = 'log') {
   249→        const timestamp = Date.now();
   250→        const id = `${prefix}-${timestamp}`;
   251→
   252→        const fullContent = `**Timestamp**: ${new Date().toISOString()}\n\n${content}`;
   253→        await this.write(id, title, fullContent);
   254→
   255→        return id;
   256→    }
   257→
   258→    /**
   259→     * Create a task note
   260→     *
   261→     * @param {Object} task - Task object
   262→     * @param {string} task.id - Task ID
   263→     * @param {string} task.title - Task title
   264→     * @param {string} [task.description] - Task description
   265→     * @param {string} [task.status] - Task status
   266→     * @param {string} [task.priority] - Task priority
   267→     * @returns {Promise<void>}
   268→     *
   269→     * @example
   270→     * await anytype.createTask({
   271→     *     id: '123',
   272→     *     title: 'Fix authentication bug',
   273→     *     description: 'Users unable to login',
   274→     *     status: 'in-progress',
   275→     *     priority: 'high'
   276→     * });
   277→     */
   278→    async createTask(task) {
   279→        const content = `
   280→**Status**: ${task.status || 'pending'}
   281→**Priority**: ${task.priority || 'normal'}
   282→
   283→## Description
   284→${task.description || 'No description provided.'}
   285→
   286→## Notes
   287→${task.notes || ''}
   288→`.trim();
   289→
   290→        await this.write(`task-${task.id}`, task.title, content);
   291→    }
   292→
   293→    /**
   294→     * Update task status
   295→     *
   296→     * @param {string} taskId - Task ID
   297→     * @param {string} status - New status
   298→     * @returns {Promise<void>}
   299→     *
   300→     * @example
   301→     * await anytype.updateTaskStatus('123', 'completed');
   302→     */
   303→    async updateTaskStatus(taskId, status) {
   304→        const id = `task-${taskId}`;
   305→        const content = await this.read(id);
   306→
   307→        if (!content) {
   308→            throw new Error(`Task ${taskId} not found`);
   309→        }
   310→
   311→        // Update status line
   312→        const updated = content.replace(
   313→            /\*\*Status\*\*: .+/,
   314→            `**Status**: ${status}`
   315→        );
   316→
   317→        await this.update(id, updated);
   318→    }
   319→}
   320→
   321→module.exports = AnyTypeHelper;
   322→
   323→// Example usage:
   324→if (require.main === module) {
   325→    (async () => {
   326→        const anytype = new AnyTypeHelper();
   327→
   328→        console.log('Testing AnyType Helper...');
   329→
   330→        // Write a test note
   331→        await anytype.write('test-note', 'Test Note', 'This is a test note from OpenClaw.');
   332→
   333→        // List all notes
   334→        const notes = await anytype.list();
   335→        console.log('Synced notes:', notes);
   336→
   337→        // Read the note
   338→        const content = await anytype.read('test-note');
   339→        console.log('Note content:', content);
   340→
   341→        // Append to note
   342→        await anytype.append('test-note', '\n\n## Update\nAppended content.');
   343→
   344→        // Update note
   345→        await anytype.update('test-note', '# Test Note\n\nCompletely updated content.');
   346→
   347→        // Check existence
   348→        console.log('Exists:', await anytype.exists('test-note'));
   349→
   350→        // Delete note
   351→        await anytype.delete('test-note');
   352→
   353→        console.log('✓ All tests passed!');
   354→    })();
   355→}
